   "9": "한 번은 먼 길을 떠나게 되는 달이에요. 사람은 잘 가려 사귀고, 걱정은 혼자 끌어안지 말고 일기장에라도 적어 보세요. 적다 보면 길이 보여요.",
   "10": "기운이 빠지는 달이에요. 몸이 무거우면 쉬어 가세요. 쓴맛이 가면 단맛이 오니 지금은 차분히 버티는 쪽을 택해 보세요.",
   "11": "물가를 조심하면 좋은 달이에요. 물과 얽힌 일은 함부로 벌이지 말고, 욕실 미끄럼과 배관을 미리 점검해 두세요. 미리 살펴 두면 마음이 편해요.",
