  "flow": "gggogggggcoo",
  "months": {
   "1": "애써 온 일이 알찬 결실로 여무는 달이에요. 뜻밖의 돈으로 살림이 늘거나 아이 소식이 들려와요. 가까운 사람이 거들어 주니 도움을 청할 일이 있으면 망설이지 말고 말해 보세요.",
   "2": "마음이 맑고 개운한 달이에요. 도와주는 사람 덕에 뜻하지 않은 이득이 생기니 고마움을 꼭 전해 주세요. 서쪽에서 오는 연락에는 빨리 답하면 좋아요.",
   "3": "묵은 걱정이 봄눈 녹듯 사라지는 달이에요. 나서서 움직이면 구하는 대로 손에 들어와요. 길에서 만나는 사람이 도와줄 사람일 수 있으니 인사를 아끼지 마세요.",
   "4": "몸이 한가롭고 마음이 넉넉한 달이에요. 살림이 늘고 식구들도 편안히 지내요. 여유 있을 때 집안 곳곳을 손봐 두고, 식구들과 가까운 나들이도 다녀와 보세요.",
   "5": "뜻밖에 이름이 알려져 많은 사람의 존중을 받는 달이에요. 벌이는 일마다 잘 여물어요. 아이들 쪽에 작은 걱정이 있을 수 있으니 아이 이야기를 찬찬히 들어 주세요.",
   "6": "거칠던 일이 잘 다듬어져 큰 그릇이 되어 가는 달이에요. 내 힘으로 공을 세울 수 있어요. 멀리서 도와줄 사람이 오니 새 제안에 귀 기울여 보세요.",
   "7": "서류에 기쁜 소식이 담겨 자리와 이름이 함께 따라오는 달이에요. 이익이 여러 곳에 있으니 망설일 까닭이 없어요. 미뤄 둔 계약이나 신청서를 이달에 과감히 내 보세요.",
   "8": "동쪽에서 좋은 일이 활짝 피어나는 달이에요. 결혼이나 아기 소식으로 집안이 환해지고 살림 터전도 넓어져요. 온 식구가 모여 축하하는 자리를 꾸려 보세요.",
   "9": "뜻밖의 공으로 이름이 여러 곳에 퍼지는 달이에요. 돈이 넉넉해 마음까지 여유로워져요. 받은 복을 나누면 더 커지니 어려운 이웃에게 작은 도움을 건네 보세요.",
   "10": "옳고 그름을 두고 다툴 일이 생기는 달이에요. 분한 마음이 들어도 참고 양보하면 뒤에 반가운 일로 돌아와요. 너그러운 마음을 지키면 좋은 인연도 만나요.",
   "11": "좋은 기운이 이어져 하던 일은 늘고 새 일도 순조로운 달이에요. 이성 관계는 선을 분명히 하면 오해가 없어요. 밤 모임은 일찍 마치고 돌아와 보세요.",
   "12": "돈이 넉넉하고 몸과 마음이 두루 건강한 달이에요. 가는 곳마다 이득이 생겨요. 송년 모임에서 말이 거칠어지면 웃으며 먼저 일어서는 게 좋아요."
  }
