   "11": "아이들 쪽에 작은 걱정이 생기는 달이지만 크게 마음 졸이지 않아도 돼요. 한 박자 쉬었다가 말하면 오해가 금방 풀려요.",
   "12": "몸이 무거울 수 있으니 쉬어 가는 달이에요. 연말로 갈수록 힘든 기운이 물러나고 좋은 일이 생겨요. 새해에 힘이 붙도록 푹 쉬어 주세요."
