   "2": "온 산천에 봄기운이 번져 잠든 것들이 깨어나는 달이에요. 곳곳에 돈이 있고 손대는 일마다 도와줄 사람이 붙어요. 때를 타서 벌인 일이 몇 곱의 기쁨으로 돌아오니 망설이지 말고 시작해 보세요.",
   "3": "어려움이 걷히고 밝은 흐름이 되돌아오는 달이에요. 꾀하던 일은 마음껏 펼쳐 보세요. 살림이 늘고 집에 새 식구가 들 수도 있으니 방 한 칸을 정리해 두면 좋아요.",
   "4": "복이 내려 기쁜 일이 생기는 달이에요. 도와주는 사람이 힘을 보태 하나를 바랐는데 열을 거둬요. 다만 남쪽 길은 이롭지 않으니 그쪽으로 떠날 약속은 다음 달로 미뤄 두세요.",
   "5": "바라던 일이 남김없이 이뤄져 집안이 화평하고 식구들이 넉넉하게 지내는 달이에요. 기쁜 일과 함께 직함도 따라요. 어렵던 시절을 잊지 않고 나누면 복이 더 커져요.",
   "6": "돈과 살림이 가득해 넉넉함을 마음껏 누리는 달이에요. 몸도 편안하고 곳곳에 좋은 일이 있어요. 넉넉한 김에 주변의 어려운 사람을 한 번 돌아보면 그 마음이 오래 남아요.",
   "7": "하늘과 땅이 함께 밀어주는 듯 막힘없이 탄탄대로를 걷는 달이에요. 동쪽에서 온 사람과 손잡으면 큰돈을 얻어요. 하는 일마다 매듭이 지어지니 좋은 동반자와의 약속을 소중히 지켜 주세요.",
   "8": "소망을 이루고 편안한 가운데 일을 펼치는 달이에요. 먼 곳에 기회가 보여도 흐름이 바뀔 수 있으니 떠나기 전에 두 번 세 번 따져 보세요. 서두르지 않는 것이 이달의 지혜예요.",
   "9": "뜰 앞 나무에 향기가 퍼지듯 반가운 소식이 오는 달이에요. 아기 소식 같은 기쁜 일을 기대해도 좋아요. 지출이 늘 수 있으니 큰 지출은 미리 줄여 두면 걱정이 기쁨으로 바뀌어요.",
   "10": "물고기가 물살을 거슬러 오르듯 기운이 솟는 달이에요. 돈줄이 바깥 길목에 깔려 있으니 발품을 팔면 손에 들어와요. 새 식구 소식에 집이 웃음으로 가득할 수 있어요.",
   "11": "운이 활짝 피어 복이 끊이지 않는 달이에요. 가는 곳마다 막힘없이 잘되니 온 집안이 넉넉해요. 돈 흐름은 크게 좋지만 말실수로 뒷말이 붙지 않게 말을 곱게 다듬어 보세요.",
   "12": "집안 어른 건강만 잘 챙기면 기쁜 일이 이어지는 달이에요. 어려운 흐름이 복으로 바뀌고 돈과 살림이 함께 늘어요. 한 해 마무리 자리에서 고마운 사람들을 챙기며 한 해를 닫아 보세요."
